import{_ as e,o as d,c as r,ag as s}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 25 — Testing","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_25_Testing.md","filePath":"todo/study_plan/parts/Part_25_Testing.md"}'),o={name:"todo/study_plan/parts/Part_25_Testing.md"};function a(i,t,n,l,c,h){return d(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="part-25-—-testing" tabindex="-1">Part 25 — Testing <a class="header-anchor" href="#part-25-—-testing" aria-label="Permalink to &quot;Part 25 — Testing&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Light touch — solid baseline; pass through during overflow days. <strong>Budget: ~1-2 hrs (overflow slot).</strong></p></blockquote><h2 id="_25-testing-—-topic-inventory" tabindex="-1">25 Testing — topic inventory <a class="header-anchor" href="#_25-testing-—-topic-inventory" aria-label="Permalink to &quot;25 Testing — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>Test pyramid — many unit, some integration, few e2e</td><td>🔴 💼 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>2</td><td>Unit tests — JUnit 5 (Jupiter), AssertJ, Hamcrest</td><td>🔴 💼</td><td>MP</td><td>1 hr 45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: JUnit 5 test class with @ParameterizedTest + @MethodSource + AssertJ chained assertions (15 min)</td></tr><tr><td>3</td><td>Mocking — Mockito basics, when to mock vs not (rule: mock at boundaries, not internals)</td><td>🔴 💼</td><td>MP</td><td>2 hrs 15 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Mockito @Mock + @InjectMocks + when().thenReturn() + verify().times(N) (15 min)</td></tr><tr><td>4</td><td>Spring slice tests — @WebMvcTest, @DataJpaTest, @JsonTest, @WebFluxTest</td><td>🔴 💼</td><td>MP</td><td>2 hrs 20 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: @WebMvcTest one controller, mock its service via @MockBean, hit via MockMvc (20 min)</td></tr><tr><td>5</td><td>Spring full-context tests — @SpringBootTest, MockMvc, TestRestTemplate</td><td>🔴 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>Arrange-Act-Assert (AAA) structure</td><td>🔴 💼</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>One concept per test (not necessarily one assertion call)</td><td>🔴 💼</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>Naming — <code>should_X_when_Y</code> or BDD <code>given/when/then</code></td><td>🔴 💼</td><td>M</td><td>30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>Test isolation — no order dependence, no shared mutable state</td><td>🔴 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Load testing — JMeter, Gatling, k6, Locust</td><td>🔴 💼 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 8 load testing)</td></tr><tr><td>11</td><td>Integration tests — with real DB, real Redis, real Kafka</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>TestContainers — Postgres, MySQL, Redis, Kafka, Elasticsearch</td><td>🟠 💼</td><td>MP</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: @Testcontainers + PostgreSQLContainer for an integration test against a real Postgres (30 min)</td></tr><tr><td>13</td><td>Contract testing — Pact, Spring Cloud Contract (consumer-driven)</td><td>🟠 💼</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>WireMock for external HTTP</td><td>🟠 💼</td><td>MP</td><td>1 hr 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>15</td><td>EmbeddedKafka, embedded Redis</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>16</td><td>Test data builders, ObjectMother pattern</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>17</td><td>Fixtures vs factories</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>18</td><td>TDD — when it helps, when it doesn&#39;t</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>19</td><td>Coverage — JaCoCo; line vs branch coverage and their limits</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>20</td><td>Profiling under load — async-profiler, JFR</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 8 profiling)</td></tr><tr><td>21</td><td>Chaos engineering — Chaos Monkey, Gremlin, Litmus</td><td>🟠 💼</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>22</td><td>Game days — planned failure injection</td><td>🟠 💼</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>23</td><td>Test pyramid inversion — when API tests dominate (microservices reality)</td><td>🟡</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~12 hrs</td><td>~1.1 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~28.5 hrs</td><td>~2.6 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡)</td><td>~29.25 hrs</td><td>~2.65 wk</td><td></td></tr></tbody></table><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Test pyramid — what shape does it have at your KYC platform? <ul><li><strong>Why asked:</strong> Real-world architecture. Classic: many unit (cheap, fast) + some integration (real DB / Redis) + few e2e (browser / full stack). Microservices reality: pyramid can invert toward &quot;integration honeycomb&quot; — heavy on contract + integration tests because mocking inter-service boundaries doesn&#39;t catch enough.</li></ul></li><li><strong>Q:</strong> What&#39;s &quot;mock at boundaries, not internals&quot;? <ul><li><strong>Why asked:</strong> Test design senior signal. Mock the external API, the database, the message broker — things you don&#39;t own / can&#39;t run cheaply. Don&#39;t mock your own service / repository / utility class — testing the mock instead of the real code. Internal class collaboration should usually be tested integration-style (within the bounded context).</li></ul></li><li><strong>Q:</strong> Walk through @WebMvcTest vs @SpringBootTest. <ul><li><strong>Why asked:</strong> Spring testing knowledge. @WebMvcTest: slice — loads only web layer for one controller. Fast (~1s context). Use for controller-level testing in isolation. @SpringBootTest: full context. Slow (~10s+). Use for end-to-end Spring testing OR integration testing across the whole app.</li></ul></li><li><strong>Q:</strong> TDD — when does it work for you, when does it not? <ul><li><strong>Why asked:</strong> Engineering judgment. Works: well-understood logic (algorithms, business rules with clear inputs/outputs). Doesn&#39;t work as well: exploratory work, UI design, performance tuning. Senior signal: &quot;TDD where it earns its keep&quot; — pragmatic, not dogmatic.</li></ul></li><li><strong>Q:</strong> Contract testing — when does it earn its keep? <ul><li><strong>Why asked:</strong> Microservices testing. Service A consumes Service B&#39;s API. Without contract: A&#39;s tests mock B (might be wrong), B&#39;s tests don&#39;t know A&#39;s expectations. With contract (Pact / Spring Cloud Contract): A defines its expectations of B; B&#39;s CI runs A&#39;s expectations against actual B. Catches API regressions before integration.</li></ul></li><li><strong>Q:</strong> Walk through TestContainers with a real example. <ul><li><strong>Why asked:</strong> Modern integration testing. <code>@Testcontainers</code> + <code>@Container static PostgreSQLContainer&lt;?&gt; pg = new PostgreSQLContainer&lt;&gt;(&quot;postgres:16&quot;)</code>. Test runs against ephemeral Postgres container. Cleans up after. No more H2-vs-Postgres-dialect surprises.</li></ul></li><li><strong>Q:</strong> Coverage targets — what&#39;s a sensible threshold? <ul><li><strong>Why asked:</strong> Pragmatic. 70-80% line coverage is common floor. Branch coverage stricter (catches uncovered conditional branches). Don&#39;t worship 100% — last 10% often costs disproportionately. Critical paths (auth, payments, KYC verification) deserve higher coverage; logging utilities less so.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your unit test passes but the deployed app fails. The test mocked the database with H2 in-memory. Why didn&#39;t it catch the bug? <ul><li><strong>Gotcha:</strong> Dialect divergence. H2 silently accepts SQL that Postgres rejects (or vice versa). H2 doesn&#39;t behave like real Postgres on isolation levels, gap locks, certain index quirks. Fix: TestContainers with real Postgres for repository tests. Don&#39;t trust H2 for production DB validation.</li></ul></li><li><strong>Q:</strong> You wrote 100 unit tests with 90% coverage. Production has a deserialization bug. What&#39;s the gap? <ul><li><strong>Gotcha:</strong> Coverage measures lines executed, NOT scenarios validated. The bug may live in a code path that&#39;s tested but only with happy-path data. Coverage gap: edge cases, malformed input, race conditions. Property-based testing or fuzzing catches these.</li></ul></li><li><strong>Q:</strong> Your tests pass locally, fail in CI. They pass on retry. What&#39;s likely? <ul><li><strong>Gotcha:</strong> Flaky tests. Common causes: (1) time-of-day or timezone dependence, (2) test order dependence (shared state between tests), (3) network calls (DNS / external service), (4) resource leaks from prior tests, (5) thread-pool exhaustion across parallel test runners. Fix root cause, don&#39;t retry-mask.</li></ul></li><li><strong>Q:</strong> You mock <code>MyRepository</code>. Test passes. Production query has wrong WHERE clause. Why didn&#39;t the test catch it? <ul><li><strong>Gotcha:</strong> Over-mocking. The mock returned canned data, but you never validated the actual SQL / JPA query. Fix: use TestContainers + real repository for query-correctness testing. Pure mock for unrelated business logic; real DB for query logic.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Spring slice tests + TestContainers integration tests</strong> (~3 hrs combined rows 4 + 12) — modern Spring testing stack. @WebMvcTest for controllers, TestContainers for repositories, full @SpringBootTest sparingly.</li><li><strong>Contract testing with Pact</strong> (~3 hrs row 13) — KYC platform is multi-service. Consumer-driven contracts catch cross-service breaks. Worth the setup investment.</li><li><strong>Test discipline + naming + AAA</strong> (~2 hrs combined rows 6-9) — get the team to write maintainable tests. Soft skill but high leverage for codebase quality.</li><li><strong>Load testing setup with k6</strong> (~2 hrs row 10) — cross-ref Part 8. Reproducible scripts in git; tied to CI for regression catching.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up testing exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>TestContainers Postgres integration test</strong> (~60 min) — Spring Boot + <code>@Testcontainers</code> + <code>PostgreSQLContainer</code>. Test a repository method with real SQL. Verify query correctness (not just returning data shape).</li><li><strong>WireMock for external HTTP</strong> (~45 min) — service that calls a vendor API. Wire-up WireMock in test. Stub success, error, timeout scenarios. Verify your retry + fallback logic.</li><li><strong>Contract test with Pact (consumer side)</strong> (~60 min) — define consumer expectations of a vendor service. Generate the pact file. Verify provider matches. Catch a breaking change scenario.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>k6 load test pipeline</strong> (~75 min) — write a k6 script that ramps to 100 VUs over 30s, sustains 2 min, ramps down. Capture p50/p95/p99. Run against local Spring Boot service. Tie into CI (artifact upload of results).</li><li><strong>Chaos engineering experiment</strong> (~90 min) — pick a non-prod service. Inject latency on one downstream dependency (via WireMock or container CPU throttling). Verify circuit breaker activates. Document expected vs observed behavior.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~5.5 hrs</strong></td><td><strong>~0.5 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~80 min for Part 25 across 4 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Mock at boundaries, not internals — one-line rule.</strong> A. Mock external systems (DB, message broker, third-party API). Don&#39;t mock your own service classes — you&#39;d be testing the mock instead of real behavior.</p><p><strong>Q. @WebMvcTest vs @SpringBootTest?</strong> A. @WebMvcTest: slice loading only web layer for one controller (fast, isolated). @SpringBootTest: full app context (slow, end-to-end). Pick smallest scope that exercises the behavior.</p><p><strong>Q. AAA structure?</strong> A. Arrange (set up inputs + mocks), Act (call the unit under test), Assert (verify outcome). Visual separation matters; one concept per test.</p><p><strong>Q. TestContainers gain over H2?</strong> A. Real Postgres / MySQL / Redis behavior. Catches dialect divergence, isolation level quirks, gap-lock specifics. Slightly slower but radically more reliable.</p><p><strong>Q. Test pyramid — typical shape?</strong> A. Wide base of fast unit tests, narrower middle of integration tests, narrow top of e2e tests. Microservices often invert toward &quot;honeycomb&quot; — heavy integration, lighter unit.</p><p><strong>Q. Coverage threshold — sensible?</strong> A. 70-80% line coverage as floor; branch coverage stricter. Critical paths (auth, payments) higher; logging utilities lower. Don&#39;t chase 100% — diminishing returns.</p>',28)])])}const m=e(o,[["render",a]]);export{u as __pageData,m as default};
